/** Yuki in [mood], with her scarf, hair-clip flake and sparkles in [tint]. 200 × 200 viewport. */
internal fun yukiVector(mood: Mood, tint: Color): ImageVector {
  fun brush(c: Long?) = when (c) {
    null -> null
    TINT -> SolidColor(tint)
    else -> SolidColor(Color(c))
  }
  val b = ImageVector.Builder("yuki_${mood.name.lowercase()}", 120.dp, 120.dp, 200f, 200f)
  for (p in parts.getValue(mood)) {
    b.addPath(
      pathData = addPathNodes(p.d),
      fill = brush(p.fill),
      fillAlpha = p.alpha,
      stroke = brush(p.stroke),
      strokeLineWidth = p.width,
      strokeLineCap = StrokeCap.Round,
      strokeLineJoin = StrokeJoin.Round,
    )
  }
  return b.build()
}
